package httpapi

import (
	"embed"
	"io/fs"
	"log/slog"
	"net/http"
	"path"
	"strconv"
	"strings"
)

// The built single-page app is embedded so one binary is the whole product
// (Phase 6 E7). Before this, the backend answered 404 for `/dashboard` and the
// UI could only run from `vite dev`, which made "install Veylix" a two-service
// operation with no documented path.
//
// `all:` includes files that begin with `_` or `.`, which the default pattern
// skips — Vite emits hashed asset names and we must not silently drop one.
//
// The `dist` directory is generated by `.\dev.ps1 -Package` (or
// `frontend && npm run build` followed by a copy). It is committed only as a
// placeholder `.gitkeep` so `go build ./...` never fails on a fresh clone:
// see dist/.gitkeep.
//
//go:embed all:dist
var embeddedDist embed.FS

// spaAssets returns the embedded filesystem rooted at dist/.
func spaAssets() fs.FS {
	sub, err := fs.Sub(embeddedDist, "dist")
	if err != nil {
		// Cannot happen with a valid embed directive; fail loudly rather than
		// serving a blank page.
		panic("httpapi: embedded dist is unreadable: " + err.Error())
	}
	return sub
}

// spaHandler serves the embedded SPA with client-route fallback.
//
// Two rules matter for correctness:
//
//  1. A request that looks like a file (`/assets/index-abc.js`, `/favicon.svg`)
//     and does not exist answers 404 — never index.html. Returning HTML for a
//     missing script produces a confusing "Unexpected token '<'" in the browser
//     instead of an honest 404.
//  2. Any other path that is not a file is a client route, so it gets
//     index.html and the router decides (this is what makes a deep link like
//     /vpn/16 work after a hard refresh).
//
// The SPA is only mounted when a build is present; see Router.
func spaHandler(assets fs.FS) http.Handler {
	fileServer := http.FileServer(http.FS(assets))
	index, indexErr := fs.ReadFile(assets, "index.html")

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Only GET/HEAD can be SPA navigations. Anything else reaching this
		// handler is a mistake and must not be answered with HTML.
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}

		requested := strings.TrimPrefix(path.Clean("/"+r.URL.Path), "/")
		if requested == "" {
			requested = "index.html"
		}

		if info, err := fs.Stat(assets, requested); err == nil && !info.IsDir() {
			// A real asset. Vite fingerprints filenames, so the content for a
			// given URL never changes: cache it for a year, immutable.
			if strings.HasPrefix(requested, "assets/") {
				w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
			}
			fileServer.ServeHTTP(w, r)
			return
		}

		// A missing file must stay a 404 (see rule 1 above).
		if path.Ext(requested) != "" && !strings.HasSuffix(requested, ".html") {
			http.NotFound(w, r)
			return
		}

		if indexErr != nil {
			slog.Error("httpapi: SPA index missing", "err", indexErr)
			WriteError(w, http.StatusServiceUnavailable, "ui_unavailable",
				"the interface was not built into this binary")
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.WriteHeader(http.StatusOK)
		if r.Method == http.MethodHead {
			return
		}
		_, _ = w.Write(index)
	})
}

// SPAStatus reports whether an SPA build is embedded, for the startup log and
// for `GET /api/ready`.
//
// A build counts as present only when index.html exists — an empty dist/
// directory (the fresh-clone placeholder) must not claim the UI is available.
func SPAStatus() (present bool, files int) {
	return spaStatus(spaAssets())
}

// spaStatus is the testable core of SPAStatus.
func spaStatus(assets fs.FS) (present bool, files int) {
	hasIndex := false
	err := fs.WalkDir(assets, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil // an unreadable subtree simply does not count
		}
		if d.IsDir() {
			return nil
		}
		files++
		if p == "index.html" {
			hasIndex = true
		}
		return nil
	})
	if err != nil {
		return false, files
	}
	return hasIndex, files
}

// hasSPA is the cheap check the router uses to decide whether to mount the
// catch-all route at all.
func hasSPA() bool {
	ok, _ := SPAStatus()
	return ok
}

// spaFS returns the embedded SPA filesystem and whether it contains a build.
//
// Returning (fs, false) lets the router mount an honest JSON 404 for UI paths
// instead of a handler that would fail per request.
func spaFS() (fs.FS, bool) {
	if !hasSPA() {
		return nil, false
	}
	return spaAssets(), true
}

// spaStatusText is the operator-facing summary reported by GET /api/ready.
func spaStatusText() string {
	present, files := SPAStatus()
	if !present {
		return "not_embedded"
	}
	return "embedded:" + strconv.Itoa(files) + "_files"
}
